const defaultIpA = "192.168.2.41";
const defaultIpB = "192.168.2.42";
const validIp = value => {
    const parts = String(value || "").trim().split(".");
    return parts.length === 4 && parts.every(part => /^\d{1,3}$/.test(part) && Number(part) >= 0 && Number(part) <= 255);
};

let ipA = flow.get("magentatvTargetIpA") || flow.get("magentatvTargetIp") || defaultIpA;
let ipB = flow.get("magentatvTargetIpB") || defaultIpB;
let enabledA = flow.get("magentatvBoxAEnabled");
if (enabledA === undefined) enabledA = true;
let enabledB = flow.get("magentatvBoxBEnabled");
if (enabledB === undefined) enabledB = false;
let scanMode = flow.get("magentatvScanMode") || "sequential";

function activeBoxes() {
    if (scanMode === "list") return [{ip: ipA, box: "A"}, {ip: ipB, box: "B"}];
    const boxes = [];
    if (enabledA) boxes.push({ip: ipA, box: "A"});
    if (enabledB) boxes.push({ip: ipB, box: "B"});
    return boxes;
}

function infoSourceIp() {
    if (scanMode === "list") return ipA;
    if (enabledA) return ipA;
    if (enabledB) return ipB;
    return ipA;
}

function ipBoxConfigFile() {
    const svcDir = flow.get("magentatvStorageServiceDir") || ((flow.get("magentatvSystem") === "development" ? "/home/pi/project/zarpy/rec" : "/mnt/rec") + "/services");
    return {
        filename: svcDir + "/magentatv_ip_config.json",
        payload: JSON.stringify({version:2, saved_at:new Date().toISOString(), targetIpA: ipA, targetIpB: ipB, boxAEnabled: enabledA, boxBEnabled: enabledB}, null, 2)
    };
}

function dashboardBoxState(extra = {}) {
    return {payload:{
        targetIpA: ipA,
        targetIpB: ipB,
        boxAEnabled: enabledA,
        boxBEnabled: enabledB,
        scanMode,
        ...extra
    }};
}

if (msg.topic === "frontend-ready") {
    const uiMsg = dashboardBoxState({
        system: flow.get("magentatvSystem") || "production",
        recordingEnabled: flow.get("magentatvRecordingEnabled") === true,
        directory: flow.get("magentatvDirectory") || {},
        pinConfigured: !!(flow.get("magentatvPin"))
    });
    return [null, null, msg, null, {topic:"status-check"}, uiMsg, null, msg, null];
}

if (msg.topic === "config-ip-a" || msg.topic === "config-ip-b") {
    const which = msg.topic === "config-ip-a" ? "A" : "B";
    if (!validIp(msg.payload)) {
        return [null, null, null, null, null, dashboardBoxState({configMessage:"Ungültige IPv4-Adresse für Box " + which}), null];
    }
    const value = String(msg.payload).trim();
    if (which === "A") { ipA = value; flow.set("magentatvTargetIpA", ipA); flow.set("magentatvTargetIp", ipA); }
    else { ipB = value; flow.set("magentatvTargetIpB", ipB); }

    const connectCommands = [];
    if (which === "A") connectCommands.push("connect " + ipA + ":5555");
    else connectCommands.push("connect " + ipB + ":5555");

    return [
        {payload: connectCommands},
        null,
        null,
        null,
        {topic:"status-check"},
        dashboardBoxState({configMessage:"IP für Box " + which + " gespeichert"}),
        null,
        null,
        ipBoxConfigFile()
    ];
}

if (msg.topic === "pin-save") {
    const pin = String(msg.payload || "").trim();
    if (!/^\\d{4,8}$/.test(pin)) {
        return [null, null, null, null, null, dashboardBoxState({configMessage:"Ungültige PIN: bitte 4 bis 8 Ziffern eingeben"}), null];
    }
    flow.set("magentatvPin", pin);
    flow.set("magentatvPinFailStreak", 0);
    const svcDir = flow.get("magentatvStorageServiceDir") || ((flow.get("magentatvSystem") === "development" ? "/home/pi/project/zarpy/rec" : "/mnt/rec") + "/services");
    const pinConfigFile = { filename: svcDir + "/magentatv_pin_config.json", payload: JSON.stringify({version:1, saved_at:new Date().toISOString(), pin}, null, 2) };
    return [null, null, null, null, null, dashboardBoxState({configMessage:"PIN gespeichert"}), null, null, pinConfigFile];
}

if (msg.topic === "pin-reset-lock") {
    flow.set("magentatvPinFailStreak", 0);
    return [null, null, null, null, null, dashboardBoxState({configMessage:"PIN-Sperre zurückgesetzt"}), null];
}

if (msg.topic === "box-a-enabled" || msg.topic === "box-b-enabled") {
    const which = msg.topic === "box-a-enabled" ? "A" : "B";
    const value = msg.payload === true;
    if (scanMode === "list") {
        return [null, null, null, null, null, dashboardBoxState({configMessage:"Im Listenmodus sind beide Boxen aktiv"}), null];
    }
    if (which === "A") { enabledA = value; flow.set("magentatvBoxAEnabled", enabledA); }
    else { enabledB = value; flow.set("magentatvBoxBEnabled", enabledB); }
    return [null, null, null, null, null, dashboardBoxState({configMessage:"Box " + which + (value ? " aktiviert" : " deaktiviert")}), null, {topic:msg.topic,payload:value}, ipBoxConfigFile()];
}

if (msg.topic === "status-check") return [null, null, null, null, msg, null, null];
if (msg.topic === "record-control") return [null, null, null, msg, null, null, null];
if (msg.topic === "excel-export") return [null, null, null, null, null, null, msg];
if (msg.topic === "video-capture-save" || msg.topic === "system-set") return [null,null,null,null,null,null,null,msg];

if (msg.topic === "scan-interval") { flow.set("magentatvScanInterval", Math.max(8, Math.min(3600, Math.round(Number(msg.payload) || 10)))); }

// Automatik-Config Interval sofort beim Neustart global sichern
if (msg.topic === "automation-config-load") {
    const x = msg.payload || {};
    if (x.interval) flow.set("magentatvScanInterval", Math.max(8, Math.min(3600, Number(x.interval))));
}

if (["automation-start-number","automation-start-channel-up","automation-start-list"].includes(msg.topic)) {
    const x = msg.payload || {};
    flow.set("magentatvScanInterval", Math.max(8, Math.min(3600, Math.round(Number(x.interval) || Number(flow.get("magentatvScanInterval") || 10)))));
}

if ([
    "scan", "scan-interval", "scan-list", "scan-list-load",
    "scan-start-config", "automation-start", "automation-stop", "automation-reset",
    "automation-start-number", "automation-start-channel-up", "automation-start-list", "automation-stop-all",
    "directory-load", "directory-import", "list-offset", "automation-config-load", "autostart-config"
].includes(msg.topic)) {
    return [null, null, msg, null, null, null, null];
}

if (msg.topic === "connect") {
    msg.payload = [ipA, ipB].map(target => "connect " + target + ":5555");
    return [msg, null, null, null, null, null, null];
}

if (msg.topic === "key-all-boxes") {
    const key = String(msg.payload || "");
    if (!/^KEYCODE_[A-Z0-9_]+$/.test(key)) return null;
    const ips = [ipA, ipB].filter((ip, i, all) => validIp(ip) && all.indexOf(ip) === i);
    if (!ips.length) return [null, null, null, null, null, dashboardBoxState({configMessage:"TV-Taste nicht gesendet: keine gültige Box-IP"}), null];
    return [{topic:"key-command", payload: ips.map(ip => "-s " + ip + ":5555 shell input keyevent " + key)}, null, null, null, null, dashboardBoxState({configMessage:"TV-Taste an " + ips.length + " konfigurierte Box(en) gesendet"}), null];
}

if (msg.topic === "key") {
    const key = String(msg.payload || "");
    if (!/^KEYCODE_[A-Z0-9_]+$/.test(key)) return null;

    const boxes = activeBoxes();
    const infoIp = infoSourceIp();
    const keyMsg = {
        topic:"key-command",
        payload: boxes.map(b => "-s " + b.ip + ":5555 shell input keyevent " + key)
    };

    if (key === "KEYCODE_CHANNEL_UP" || key === "KEYCODE_CHANNEL_DOWN") {
        const direction = key === "KEYCODE_CHANNEL_UP" ? "up" : "down";
        const requestedAction = direction === "up" ? "CH+" : "CH-";
        const automatic = msg.scanGenerated === true || msg.automationGenerated === true;
        flow.set("lastRequestedChannel", requestedAction);
        const infoMsg = {
            topic:"info",
            requestedChannel:requestedAction,
            channelDirection:direction,
            scanGenerated:automatic,
            targetIp:infoIp,
            payload:"refresh"
        };
        const uiMsg = {payload:{
            requestedChannel:requestedAction,
            actualChannel:"",
            loading:true,
            status:direction === "up" ? "CH+ angefordert" : "CH- angefordert"
        }};
        return [keyMsg, infoMsg, null, null, null, uiMsg, null];
    }

    const analysisKeys = {
        KEYCODE_BACK: "BACK / EXIT",
        KEYCODE_HOME: "HOME",
        KEYCODE_INFO: "INFO",
        KEYCODE_TV: "TV"
    };

    if (analysisKeys[key]) {
        const requestedAction = analysisKeys[key];
        flow.set("lastRequestedChannel", requestedAction);
        const infoMsg = {
            topic:"info",
            requestedChannel:requestedAction,
            remoteAction:key,
            scanGenerated:false,
            targetIp:infoIp,
            payload:"refresh"
        };
        const uiMsg = {payload:{
            requestedChannel:requestedAction,
            actualChannel:"",
            loading:true,
            status:requestedAction + " ausgeführt, Senderdaten werden aktualisiert"
        }};
        return [keyMsg, infoMsg, null, null, null, uiMsg, null];
    }

    return [keyMsg, null, null, null, null, null, null];
}

if (msg.topic === "channel") {
    const channel = String(msg.payload || "").trim();
    if (!/^\d{1,3}$/.test(channel)) return null;

    const channelBRaw = msg.channelB !== undefined ? String(msg.channelB).trim() : channel;
    const channelB = /^\d{1,3}$/.test(channelBRaw) ? channelBRaw : channel;

    const keyCommandsFor = (ch) => ch.split("")
        .map(digit => "input keyevent KEYCODE_" + digit)
        .join("; sleep 0.25; ");

    const boxes = activeBoxes();
    const infoIp = infoSourceIp();
    const channelMsg = {
        topic:"channel-command",
        requestedChannel:channel,
        scanGenerated:msg.scanGenerated === true,
        targetIp:infoIp,
        payload: boxes.map(b => {
            const ch = b.box === "B" ? channelB : channel;
            return "-s " + b.ip + ":5555 shell \"" + keyCommandsFor(ch) + "; sleep 0.70; input keyevent KEYCODE_ENTER\"";
        })
    };

    const infoMsg = {
        topic:"info",
        requestedChannel:channel,
        scanGenerated:msg.scanGenerated === true,
        targetIp:infoIp,
        payload:"refresh"
    };

    flow.set("lastRequestedChannel", channel);
    flow.set("lastRequestedChannelB", channelB);

    const uiMsg = {payload:{
        requestedChannel:channel,
        requestedChannelB:channelB,
        actualChannel:"",
        loading:true,
        status: channelB !== channel
            ? "Box A: Sender " + channel + " · Box B: Sender " + channelB + " werden angesteuert"
            : "Sender " + channel + " wird angesteuert"
    }};

    const cap=msg.scanGenerated===true?{topic:"video-capture-start",payload:{channel,channelB,scanInterval:flow.get("magentatvScanInterval")||10}}:null;return [channelMsg,infoMsg,null,null,null,uiMsg,null,cap];
}

return null;

const ipA=flow.get("magentatvTargetIpA")||flow.get("magentatvTargetIp")||"192.168.2.41";
const ipB=flow.get("magentatvTargetIpB")||"192.168.2.42";
const check=(target)=>"adb -s "+target+":5555 get-state 2>/dev/null | grep -qx device && echo ONLINE || echo OFFLINE";
msg.payload='-c "echo -n A:; '+check(ipA)+'; echo -n B:; '+check(ipB)+'"';
return msg;

const raw=String(msg.payload||"");
const mA=raw.match(/A:(ONLINE|OFFLINE)/i);
const mB=raw.match(/B:(ONLINE|OFFLINE)/i);
if(!mA&&!mB)return null;
const onA=mA?mA[1].toUpperCase()==="ONLINE":false;
const onB=mB?mB[1].toUpperCase()==="ONLINE":false;
msg.payload={
    onlineA:onA,
    onlineB:onB,
    online:onA,
    status:(onA?"Box A verbunden":"Box A nicht verbunden")+" · "+(onB?"Box B verbunden":"Box B nicht verbunden")
};
return msg;

const xml=String(msg.payload||"");

const pinScreenPattern=/PIN|Kindersicherung|Jugendschutz|Elternschutz|Zugangscode|Code eingeben/i;
if(pinScreenPattern.test(xml)){
    const pin=String(flow.get("magentatvPin")||"").trim();
    const failStreak=Number(flow.get("magentatvPinFailStreak")||0);
    const lastAttempt=Number(flow.get("magentatvPinLastAttempt")||0);
    const now=Date.now();
    const requestedChannel0=msg.requestedChannel||flow.get("lastRequestedChannel")||"";
    if(failStreak>=2){
        return [{payload:{programError:"PIN-Eingabe zweimal erfolglos - automatische Eingabe pausiert, bitte im Menü PIN pruefen und Sperre zuruecksetzen",loading:false,requestedChannel:requestedChannel0}},null,null,null,null];
    }
    if(!pin||!/^\d{4,8}$/.test(pin)){
        return [{payload:{programError:"PIN-Bildschirm erkannt, aber keine gueltige PIN im Menue hinterlegt",loading:false,requestedChannel:requestedChannel0}},null,null,null,null];
    }
    if((now-lastAttempt)<20000){
        return [{payload:{programError:"PIN-Bildschirm erkannt, Abkuehlzeit nach letztem Versuch aktiv",loading:true,requestedChannel:requestedChannel0}},null,null,null,null];
    }
    flow.set("magentatvPinLastAttempt",now);
    flow.set("magentatvPinFailStreak",failStreak+1);
    const ip=msg.targetIp||flow.get("magentatvTargetIpA")||flow.get("magentatvTargetIp")||"192.168.2.41";
    const keyCommandsFor=pin.split("").map(d=>"input keyevent KEYCODE_"+d).join("; sleep 0.25; ");
    const pinMsg={
        requestedChannel:requestedChannel0,
        targetIp:msg.targetIp,
        scanGenerated:msg.scanGenerated===true,
        infoStartedAt:msg.infoStartedAt,
        infoAttempt:msg.infoAttempt,
        payload:"-s "+ip+":5555 shell \""+keyCommandsFor+"; sleep 0.5; input keyevent KEYCODE_DPAD_CENTER; sleep 0.8; input keyevent KEYCODE_DPAD_CENTER\""
    };
    return [{payload:{programError:"",loading:true,status:"PIN-Bildschirm erkannt, PIN wird automatisch eingegeben"}},null,null,null,pinMsg];
}

const errorScreenPattern=/Sender nicht abspielbar/i;
if(errorScreenPattern.test(xml)){
    const requestedChannel0=msg.requestedChannel||flow.get("lastRequestedChannel")||"";
    const ip=msg.targetIp||flow.get("magentatvTargetIpA")||flow.get("magentatvTargetIp")||"192.168.2.41";
    return [
        {payload:{programError:"Fehler: 'Sender nicht abspielbar'. Zurück-Taste gesendet.",loading:false,status:"Nicht abspielbar",requestedChannel:requestedChannel0,actualChannel:requestedChannel0}},
        null,null,null,
        {payload:"-s "+ip+":5555 shell \"input keyevent KEYCODE_BACK\""}
    ];
}

flow.set("magentatvPinFailStreak",0);

const matches=[...xml.matchAll(/content-desc="(Kanal [^"]+)"/g)];
if(!matches.length){
    const startedAt=Number(msg.infoStartedAt)||Date.now();
    const attempt=Number(msg.infoAttempt)||1;
    const elapsed=Date.now()-startedAt;
    const requestedChannel=msg.requestedChannel||flow.get("lastRequestedChannel")||"";
    const intervalMs=Math.max(8,Number(flow.get("magentatvScanInterval"))||10)*1000;
    const budgetMs=Math.min(8000,Math.max(2500,intervalMs-800));
    if(elapsed<budgetMs&&attempt<4){
        const retryMsg={topic:"info-retry",requestedChannel,targetIp:msg.targetIp,scanGenerated:msg.scanGenerated===true,payload:"refresh",infoStartedAt:startedAt,infoAttempt:attempt};
        return [{payload:{programError:"",loading:true,status:"Sendungsdaten werden erneut geprüft (Versuch "+(attempt+1)+")"}},null,null,retryMsg,null];
    }
    return [{payload:{programError:"Keine Sendungsdaten gefunden nach "+attempt+" Versuchen ("+Math.round(elapsed/100)/10+"s)",loading:false,requestedChannel}},null,null,null,null];
}

const raw=matches.map(x=>x[1]).sort((a,b)=>b.length-a.length)[0]
    .replace(/&amp;/g,"&")
    .replace(/&quot;/g,'"')
    .replace(/&#39;/g,"'");
const p=raw.split(',').map(x=>x.trim()).filter(Boolean);
const o={channel:null,station:p[1]||"",title:"",remaining_minutes:null,duration_minutes:null,season:null,episode:null,genre:"",quality:"",raw};
let m=(p[0]||"").match(/^Kanal\s+(\d+)/i);
if(m)o.channel=+m[1];
let s=p.length;
for(let i=2;i<p.length;i++){
    if(/^(Instant Restart|Noch\s+\d+\s+Min\.?|\d+\s+Min\.?|S\d+\s+F\d+|(High|Standard|Ultra-High)-Definition)$/i.test(p[i])){s=i;break;}
}
o.title=p.slice(2,s).join(', ');
for(const v of p.slice(s)){
    if((m=v.match(/^Noch\s+(\d+)\s+Min/i)))o.remaining_minutes=+m[1];
    else if((m=v.match(/^(\d+)\s+Min/i)))o.duration_minutes=+m[1];
    else if((m=v.match(/^S(\d+)\s+F(\d+)/i))){o.season=+m[1];o.episode=+m[2];}
    else if(/Definition/i.test(v))o.quality=v;
    else if(!/^Instant Restart$/i.test(v))o.genre=v;
}

const requested=String(msg.requestedChannel||flow.get("lastRequestedChannel")||"");
const actual=String(o.channel===null?"":o.channel);
flow.set("activeChannel",actual);
let directory=flow.get("magentatvDirectory")||{};
if(actual&&o.station){directory[actual]=o.station;flow.set("magentatvDirectory",directory);const ts=flow.get("magentatvDirectoryTimestamps")||{};ts[actual]=Date.now();flow.set("magentatvDirectoryTimestamps",ts);}
let resultStatus;
if(requested === "CH+") resultStatus="CH+ ausgeführt, Sender " + actual + " erkannt";
else if(requested === "CH-") resultStatus="CH- ausgeführt, Sender " + actual + " erkannt";
else if(["BACK / EXIT","HOME","INFO","TV"].includes(requested)) resultStatus=requested + " ausgeführt, Sender " + actual + " erkannt";
else if(!requested) resultStatus="Sender nach CH-Taste erkannt";
else if(Number(requested)===Number(actual)) resultStatus="Sender bestätigt";
else resultStatus="Abweichender Sender angesteuert";
const dashboardMsg={payload:{program:o,directory,requestedChannel:requested,actualChannel:actual,loading:false,status:resultStatus}};
const logMsg=msg.scanGenerated===true?{payload:{timestamp:new Date().toISOString(),requested_channel:requested,actual_channel:actual,...o}}:null;
const directoryMsg={filename:(flow.get("magentatvStorageServiceDir")||((flow.get("magentatvSystem")==="development"?"/home/pi/project/zarpy/rec":"/mnt/rec")+"/services"))+"/magentatv_channel_directory.json",payload:JSON.stringify({stations:directory},null,2)};
return [dashboardMsg,logMsg,directoryMsg,null,null];

let run = context.get("run") === true;
let automationType = context.get("automationType") || "off";
let seq = Number(context.get("seq") || 1);
let idx = Number(context.get("idx") || 0);
let interval = Number(context.get("interval") || 10);
let elapsed = Number(context.get("elapsed") || 0);
let mode = context.get("mode") || "sequential";
let list = Array.isArray(context.get("list")) ? context.get("list") : [];
let raw = String(context.get("raw") || "");
let boxOffset = Number(context.get("boxOffset") || 0);
let autostart = context.get("autostart") === true;

function maxOffset() {
    return Math.max(0, Math.floor(list.length / 2));
}

function clampOffset(v) {
    const m = maxOffset();
    if (!m) return 0;
    const n = Math.round(Number(v) || 0);
    if (n <= 0) return 0;
    return Math.min(n, m);
}
boxOffset = clampOffset(boxOffset);

function normalizeList(values) {
    return (Array.isArray(values) ? values : []).map(v => String(v).trim())
        .filter(v => /^\d{1,3}$/.test(v) && Number(v) >= 0 && Number(v) <= 999);
}

function saveState() {
    boxOffset = clampOffset(boxOffset);
    context.set("run", run);
    context.set("automationType", automationType);
    context.set("seq", seq);
    context.set("idx", idx);
    context.set("interval", interval);
    context.set("elapsed", elapsed);
    context.set("mode", mode);
    context.set("list", list);
    context.set("raw", raw);
    context.set("boxOffset", boxOffset);
    context.set("autostart", autostart);

    // NEU: Liste global bereitstellen für andere Flows/Module
    global.set("magentatvChannelList", list);
    global.set("magentatvChannelListRaw", raw);
}

function configFile() {
    return {
        filename: (flow.get("magentatvStorageServiceDir") || ((flow.get("magentatvSystem") === "development" ? "/home/pi/project/zarpy/rec" : "/mnt/rec") + "/services")) + "/magentatv_automation_config.json",
        payload: JSON.stringify({ version: 1, saved_at: new Date().toISOString(), mode, boxOffset, interval, autostart }, null, 2)
    };
}

function nextChannelB() {
    if (!list.length || !boxOffset) return null;
    return String(list[(idx + boxOffset) % list.length]);
}

function nextChannel() {
    if (automationType === "channel-up") return "CH+";
    if (automationType === "list" || mode === "list") return list.length ? String(list[idx % list.length]) : "--";
    return String(seq).padStart(3, "0");
}

function ui(extra = {}) {
    return {
        payload: {
            scanRunning: run,
            automationType,
            scanInterval: interval,
            scanMode: mode,
            autostartEnabled: autostart,
            channelList: list,
            channelListText: raw,
            scanNext: nextChannel(),
            boxOffset,
            boxOffsetMax: maxOffset(),
            scanNextB: nextChannelB(),
            listMessage: list.length ? list.length + " Sender gespeichert" : "Liste ist leer",
            ...extra
        }
    };
}

function actionMessage() {
    elapsed = 0;
    let output;
    if (automationType === "channel-up") {
        output = { topic: "key", payload: "KEYCODE_CHANNEL_UP", scanGenerated: true, automationGenerated: true };
    } else if (automationType === "list") {
        if (!list.length) return null;
        const channel = String(list[idx % list.length]);
        const channelB = boxOffset ? String(list[(idx + boxOffset) % list.length]) : channel;
        idx = (idx + 1) % list.length;
        output = { topic: "channel", payload: channel, channelB, scanGenerated: true, automationGenerated: true };
    } else {
        const channel = String(seq);
        seq = seq >= 999 ? 1 : seq + 1;
        output = { topic: "channel", payload: channel, scanGenerated: true, automationGenerated: true };
    }
    saveState();
    return output;
}

function start(type, source = {}) {
    automationType = type;
    interval = Math.max(8, Math.min(3600, Math.round(Number(source.interval) || interval || 10)));
    if (type === "list") {
        if (Array.isArray(source.channels)) list = normalizeList(source.channels);
        if (typeof source.rawText === "string") raw = source.rawText;
        if (!list.length) {
            run = false;
            automationType = "off";
            saveState();
            return [null, ui({ status: "Start nicht möglich: Senderliste ist leer" }), null];
        }
        mode = "list";
    } else {
        mode = "sequential";
    }
    run = true;
    elapsed = 0;
    saveState();
    const first = actionMessage();
    const label = type === "channel-up" ? "CH+ Scan gestartet" : type === "list" ? "Senderlistenscan gestartet" : "Nummernscan gestartet";
    return [first, ui({ loading: true, status: label }), null];
}

if (msg.topic === "frontend-ready") return [null, ui(), null];

if (msg.topic === "automation-start") msg.topic = "automation-start-list";
if (msg.topic === "automation-stop" || msg.topic === "automation-stop-all") { msg.topic = "scan"; msg.payload = "stop"; }
if (msg.topic === "automation-reset") { msg.topic = "scan"; msg.payload = "reset"; }

if (msg.topic === "directory-import") {
    const directory = msg.payload && typeof msg.payload === "object" ? msg.payload : {};
    flow.set("magentatvDirectory", directory);
    const file = {
